      </Stack>
      <Stack direction="row" sx={{ gap: 0.5 }}>
        <EditAction {...props} />
        <DeleteAction {...props} />
      </Stack>
    </Stack>
  );
}

const listViewColDef = {
  field: 'listColumn',
  renderCell: (params) => <ListViewCell {...params} />,
