import * as React from 'react';
import {
  GridActionsCellItem,
  GridColDef,
  useGridApiRef,
  GridRowParams,
  DataGridPremium,
  GridRowId,
  gridClasses,
  GridActionsCell,
  GridRenderCellParams,
  useGridApiContext,
} from '@mui/x-data-grid-premium';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import Avatar from '@mui/material/Avatar';
import Stack from '@mui/material/Stack';
import OpenIcon from '@mui/icons-material/Visibility';
import useMediaQuery from '@mui/material/useMediaQuery';
import CSSBaseline from '@mui/material/CssBaseline';
import { randomId } from '@mui/x-data-grid-generator';
import { useTheme } from '@mui/material/styles';
import { FileIcon } from './components/FileIcon';
import { DetailsDrawer } from './components/DetailsDrawer';
import { ListCell } from './components/ListCell';
import { Toolbar } from './components/Toolbar';
import { INITIAL_ROWS } from './data';
import { FILE_TYPES } from './constants';
import { RowModel, FileType } from './types';
import { formatDate, formatSize, stringAvatar } from './utils';
import { ActionDrawer } from './components/ActionDrawer';
import { RenameDialog } from './components/RenameDialog';

declare module '@mui/x-data-grid' {
  interface ToolbarPropsOverrides {
    listView: boolean;
    container: HTMLElement;
    handleDelete: (ids: GridRowId[]) => void;
    handleUpload: (event: React.ChangeEvent<HTMLInputElement>) => void;
  }
}

interface Props {
  // Injected by the documentation to work in an iframe.
  window?: () => Window;
}

interface ActionHandlers {
  setOverlayState: (state: {
    overlay: 'actions' | 'details' | 'rename' | null;
    params: Pick<GridRowParams<RowModel>, 'row'> | null;
  }) => void;
  handleDelete: (ids: GridRowId[]) => void;
}

const ActionHandlersContext = React.createContext<ActionHandlers | null>(null);

function ActionsCell(props: GridRenderCellParams) {
  const context = React.useContext(ActionHandlersContext);
  const apiRef = useGridApiContext();
  if (!context) {
    return null;
  }
  const { setOverlayState, handleDelete } = context;

  return (
    <GridActionsCell {...props}>
      <GridActionsCellItem
        label="Preview"
        icon={<OpenIcon fontSize="small" />}
        onClick={() => {
          setOverlayState({ overlay: 'actions', params: props });
        }}
        showInMenu
      />
      <GridActionsCellItem
        label="Rename"
        icon={<EditIcon fontSize="small" />}
        onClick={() =>
          apiRef.current?.startCellEditMode({
            id: props.id,
            field: 'name',
          })
        }
        showInMenu
      />
      <GridActionsCellItem
        label="Delete"
        icon={<DeleteIcon fontSize="small" />}
        onClick={() => handleDelete([props.id])}
        showInMenu
      />
    </GridActionsCell>
  );
}

const columns: GridColDef[] = [
  {
    field: 'name',
    headerName: 'Name',
    width: 350,
    editable: true,
    hideable: false,
    renderCell: (params) => {
      return (
        <Stack
          direction="row"
          sx={{ gap: 1.5, alignItems: 'center', height: '100%' }}
        >
          <FileIcon type={params.row.type} />
          {params.value}
        </Stack>
      );
    },
  },
  {
    field: 'createdBy',
    headerName: 'Owner',
    width: 200,
    renderCell: (params) => {
      const avatarProps = stringAvatar(params.value);
      return (
        <Stack direction="row" sx={{ gap: 1.5, alignItems: 'center' }}>
          <Avatar
            {...avatarProps}
            sx={{ width: 24, height: 24, fontSize: 12, ...avatarProps.sx }}
          />
          {params.value}
        </Stack>
      );
    },
  },
  {
    field: 'createdAt',
    headerName: 'Added',
    type: 'date',
    width: 200,
    valueFormatter: formatDate,
  },
  {
    field: 'updatedAt',
    headerName: 'Modified',
    type: 'date',
    width: 200,
    valueFormatter: formatDate,
  },
  {
    field: 'type',
    headerName: 'Type',
    width: 150,
  },
  {
    field: 'size',
    headerName: 'Size',
    width: 120,
    valueFormatter: formatSize,
  },
  {
    type: 'actions',
    field: 'actions',
    resizable: false,
    width: 50,
    renderCell: (params) => <ActionsCell {...params} />,
  },
];

export default function ListViewAdvanced({ window }: Props) {
  // This is used only for the example - renders the drawer inside the container
  const container = window !== undefined ? window().document.body : undefined;

  const theme = useTheme();
  const isBelowMd = useMediaQuery(theme.breakpoints.down('md'));

  const isDocsDemo = window !== undefined;
  const isListView = isDocsDemo ? true : isBelowMd;

  const apiRef = useGridApiRef();

  const [loading, setLoading] = React.useState(false);

  const [overlayState, setOverlayState] = React.useState<{
    overlay: 'actions' | 'details' | 'rename' | null;
    params: Pick<GridRowParams<RowModel>, 'row'> | null;
  }>({
    overlay: null,
    params: null,
  });

  const handleCloseOverlay = () => {
    setOverlayState({ overlay: null, params: null });
  };

  const handleDelete = React.useCallback(
    (ids: GridRowId[]) => {
      apiRef.current?.updateRows(ids.map((id) => ({ id, _action: 'delete' })));
    },
    [apiRef],
  );

  const handleUpdate = React.useCallback(
    (
      id: GridRowId,
      field: GridRowParams<RowModel>['columns'][number]['field'],
      value: string,
    ) => {
      const updatedAt = new Date().toISOString();
      apiRef.current?.updateRows([{ id, [field]: value, updatedAt }]);
    },
    [apiRef],
  );

  const handleUpload = React.useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      if (!event.target.files) {
        return;
      }

      const file = event.target.files[0];
      const createdAt = new Date().toISOString();

      const fileType = file.type.split('/')[1];

      // validate file type
      if (!FILE_TYPES.includes(fileType as FileType)) {
        alert('Invalid file type');
        return;
      }

      const row: RowModel = {
        id: randomId(),
        name: file.name,
        description: '',
        type: fileType as FileType,
        size: file.size,
        createdBy: 'Kenan Yusuf',
        createdAt,
        updatedAt: createdAt,
        state: 'pending',
      };

      event.target.value = '';

      // Add temporary row
      setLoading(true);
      apiRef.current?.updateRows([row]);

      // Simulate server response time
      // eslint-disable-next-line no-restricted-properties -- not visible in UI
      const timeout = Math.floor(Math.random() * 3000) + 2000;
      setTimeout(() => {
        const uploadedRow: RowModel = { ...row, state: 'uploaded' };
        apiRef.current?.updateRows([uploadedRow]);
        setOverlayState({ overlay: 'actions', params: { row } });
        setLoading(false);
      }, timeout);
    },
    [apiRef],
  );

  const listViewColDef: GridColDef = React.useMemo(
    () => ({
      field: 'listCell',
      renderCell: (params) => (
        <ListCell
          {...params}
          onOpenActions={() => {
            setOverlayState({ overlay: 'actions', params });
          }}
        />
      ),
    }),
    [],
  );

  const getEstimatedRowHeight = () => {
    const density = apiRef.current?.state?.density;

    if (isListView) {
      switch (density) {
        case 'compact':
          return 47;
        case 'standard':
          return 67;
        case 'comfortable':
          return 97;
        default:
          return 67;
      }
    } else {
      switch (density) {
        case 'compact':
          return 47;
        case 'standard':
          return 55;
        case 'comfortable':
          return 63;
        default:
          return 55;
      }
    }
  };

  const getRowHeight = React.useCallback(
    () => (isListView ? 'auto' : undefined),
    [isListView],
  );

  const actionHandlers = React.useMemo<ActionHandlers>(
    () => ({
      setOverlayState,
      apiRef,
      handleDelete,
    }),
    [apiRef, handleDelete],
  );

  return (
    <React.Fragment>
      <CSSBaseline />
      <div
        style={{
          maxWidth: '100%',
          height: 600,
        }}
      >
        <ActionHandlersContext.Provider value={actionHandlers}>
          <DataGridPremium
            apiRef={apiRef}
            rows={INITIAL_ROWS}
            columns={columns}
            loading={loading}
            slots={{ toolbar: Toolbar }}
            showToolbar
            slotProps={{
              toolbar: {
                listView: isListView,
                container,
                handleDelete,
                handleUpload,
              },
              loadingOverlay: {
                variant: 'linear-progress',
              },
            }}
            listView={isListView}
            listViewColumn={listViewColDef}
            pagination
            pageSizeOptions={[10]}
            initialState={{
              density: 'comfortable',
              pagination: {
                paginationModel: {
                  pageSize: 10,
                },
              },
              sorting: {
                sortModel: [{ field: 'createdAt', sort: 'desc' }],
              },
              columns: {
                columnVisibilityModel: {
                  type: false,
                },
              },
            }}
            sx={{
              border: 0,
              borderRadius: 0,
              [`& .${gridClasses.cell}`]: { display: 'flex', alignItems: 'center' },
              [`&.${gridClasses['root--densityCompact']} .${gridClasses.cell}`]: {
                py: 1,
              },
              [`&.${gridClasses['root--densityStandard']} .${gridClasses.cell}`]: {
                py: 1.5,
              },
              [`&.${gridClasses['root--densityComfortable']} .${gridClasses.cell}`]:
                {
                  py: 2,
                },
            }}
            getRowHeight={getRowHeight}
            getEstimatedRowHeight={getEstimatedRowHeight}
            onRowDoubleClick={(params) =>
              setOverlayState({ overlay: 'actions', params })
            }
            hideFooterSelectedRowCount
          />
        </ActionHandlersContext.Provider>

        <DetailsDrawer
          open={overlayState.overlay === 'details'}
          params={overlayState.params}
          listView={isListView}
          container={container}
          onDescriptionChange={(id, value) => handleUpdate(id, 'description', value)}
          onClose={handleCloseOverlay}
        />

        <ActionDrawer
          open={overlayState.overlay === 'actions'}
          params={overlayState.params}
          container={container}
          onPreview={() =>
            setOverlayState({ overlay: 'details', params: overlayState.params })
          }
          onRename={() =>
            setOverlayState({ overlay: 'rename', params: overlayState.params })
          }
          onDelete={(id) => {
            handleDelete([id]);
            handleCloseOverlay();
          }}
          onClose={handleCloseOverlay}
        />

        <RenameDialog
          open={overlayState.overlay === 'rename'}
          params={overlayState.params}
          container={container}
          onSave={(id, value) => handleUpdate(id, 'name', value)}
          onClose={handleCloseOverlay}
        />
      </div>
    </React.Fragment>
  );
}

