import { GridRowId } from '@mui/x-data-grid-premium';

export type FileType =
  | 'pdf'
  | 'docx'
  | 'txt'
  | 'mp4'
  | 'mov'
  | 'webm'
  | 'jpg'
  | 'jpeg'
  | 'png'
  | 'gif'
  | 'tiff'
  | 'webp'
  | 'zip';

export type FileState = 'uploaded' | 'pending';

export type RowModel = {
  id: GridRowId;
  type: FileType;
  name: string;
  description: string;
  size: number;
  createdBy: string;
  createdAt: string;
  updatedAt: string;
  state: FileState;
};

components/DetailsDrawer.source:
import * as React from 'react';
import { GridRowId, GridRowParams } from '@mui/x-data-grid-premium';
import Divider from '@mui/material/Divider';
import Stack from '@mui/material/Stack';
import Typography from '@mui/material/Typography';
import TextField from '@mui/material/TextField';
import Avatar from '@mui/material/Avatar';
import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import VisibilityOffIcon from '@mui/icons-material/VisibilityOff';
import { Drawer, DrawerHeader, DrawerProps } from './Drawer';
import { FileIcon } from './FileIcon';
import { formatDate, formatSize, stringAvatar } from '../utils';
import { RowModel } from '../types';

interface DetailsDrawerProps extends DrawerProps {
  params: Pick<GridRowParams<RowModel>, 'row'> | null;
  listView: boolean;
  onDescriptionChange: (id: GridRowId, value: string) => void;
}

function Thumbnail() {
  return (
    <Box
      sx={(theme) => ({
        aspectRatio: '16/9',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        color: 'text.secondary',
        borderRadius: 2,
        gap: 1,
        backgroundColor: 'grey.200',
        ...theme.applyStyles('dark', {
          backgroundColor: 'grey.800',
        }),
      })}
    >
      <VisibilityOffIcon />
      <Typography variant="body2" sx={{ color: 'text.secondary' }}>
        No preview available
      </Typography>
    </Box>
  );
}

function DrawerContent(
  props: { params: Pick<GridRowParams<RowModel>, 'row'> } & Pick<
    DetailsDrawerProps,
    'onDescriptionChange' | 'onClose'
  >,
) {
  const { params, onDescriptionChange, onClose } = props;
  const [description, setDescription] = React.useState(params.row.description || '');
  const avatarProps = stringAvatar(params.row.createdBy);

  const handleSave = (event: React.MouseEvent<HTMLButtonElement>) => {
    onDescriptionChange(params.row.id, description);
    onClose(event);
  };

  return (
    <React.Fragment>
      <DrawerHeader>
        <FileIcon type={params.row.type} sx={{ width: 32, height: 32 }} />
        <Typography variant="body1">{params.row.name}</Typography>
        <Button
          variant="text"
          onClick={handleSave}
          sx={{
            flexShrink: 0,
            ml: 'auto',
            mr: -1,
          }}
        >
          Save
        </Button>
      </DrawerHeader>
      <Stack sx={{ p: 2, gap: 2 }}>
        <Thumbnail />

        <TextField
          label="Description"
          maxRows={4}
          value={description}
          onChange={(event) => setDescription(event.target.value)}
          sx={{ mt: 1 }}
          multiline
        />

        <Divider />

        <Stack sx={{ gap: 0.5 }}>
          <Typography variant="body2" sx={{ color: 'text.secondary' }}>
            Type
          </Typography>
          <Typography variant="body2">{params.row.type}</Typography>
        </Stack>

        <Stack sx={{ gap: 0.5 }}>
          <Typography variant="body2" sx={{ color: 'text.secondary' }}>
            Size
          </Typography>
          <Typography variant="body2">{formatSize(params.row.size)}</Typography>
        </Stack>

        <Stack sx={{ gap: 0.5 }}>
          <Typography variant="body2" sx={{ color: 'text.secondary' }}>
            Created
          </Typography>
          <Typography variant="body2">{formatDate(params.row.createdAt)}</Typography>
        </Stack>

        <Stack
          sx={{
            gap: 0.5,
          }}
        >
          <Typography variant="body2" sx={{ color: 'text.secondary' }}>
            Modified
          </Typography>
          <Typography variant="body2">{formatDate(params.row.updatedAt)}</Typography>
        </Stack>

        <Divider />

        <Typography variant="body2" sx={{ color: 'text.secondary' }}>
          Owner
        </Typography>

        <Stack direction="row" sx={{ gap: 1.5, alignItems: 'center' }}>
          <Avatar
            {...avatarProps}
            sx={{ width: 24, height: 24, fontSize: 12, ...avatarProps.sx }}
          />
          <Typography variant="body2">{params.row.createdBy}</Typography>
        </Stack>
      </Stack>
    </React.Fragment>
  );
}

export function DetailsDrawer(props: DetailsDrawerProps) {
  const { params, listView, onDescriptionChange, onClose, ...other } = props;
  return (
    <Drawer
      anchor={listView ? 'bottom' : 'right'}
      width={360}
      onClose={onClose}
      {...other}
    >
      {params && (
        <DrawerContent
          params={params}
          onDescriptionChange={onDescriptionChange}
          onClose={onClose}
        />
      )}
    </Drawer>
  );
}

