        onClose={() => setOpen(false)}
      >
        <DrawerHeader>
          <Typography
            sx={{
              fontWeight: 500,
            }}
          >
            Density
          </Typography>
        </DrawerHeader>

        <List>
          {DENSITY_OPTIONS.map((option) => {
